 *   - Supports baseline (no defence) or intent tracking defence
 *   - Supports multiple repetitions for variance analysis
 *   - Outputs results to JSON
 *
 * Usage:
 *   tsx src/runner.ts                                    # baseline, all scenarios
 *   tsx src/runner.ts --defence intent-tracker            # with intent tracking defence
 *   tsx src/runner.ts --defence drift-only                # embedding drift only, no judge
 *   tsx src/runner.ts --scenario naive --reps 10          # specific scenario, 10 reps
 *   tsx src/runner.ts --model claude-haiku-4-5-20251001   # different model
 *   tsx src/runner.ts --defence intent-tracker --theta-warn 0.25  # tune thresholds
 */

import { parseArgs } from "node:util";
import { writeFileSync } from "node:fs";
import { join } from "node:path";
import { getScenarios } from "../scenarios/t3-goal-hijacking.js";
import { executeScenario } from "./executor.js";
import { TurnLogger } from "./turn-logger.js";
import { PromptArmorObserver } from "./promptarmor-observer.js";
import { IntentTracker } from "./intent-tracker.js";
import { TestResult } from "./types.js";

const { values } = parseArgs({
  options: {
    scenario: { type: "string", default: "all" },
    model: { type: "string", default: "claude-sonnet-4-6" },
    repetitions: { type: "string", default: "1" },
    output: { type: "string", default: "" },
    defence: { type: "string", default: "none" },
    // Backend for IntentTracker's drift detector + judge. Defaults
    // to ollama (local 11434) — set to "bedrock" when running in
    // environments without Ollama (e.g. AI Sandbox Fargate). Bedrock
    // backend uses Cohere embed-v4 + Claude Sonnet 4.6 by default.
    backend: { type: "string", default: "ollama" },
    "embedding-model": { type: "string", default: "" },
    "judge-model": { type: "string", default: "" },
    "theta-warn": { type: "string", default: "0.3" },
    "theta-block": { type: "string", default: "0.5" },
    "delta-warn": { type: "string", default: "0.2" },
    // PromptArmor observational adapter (T-2 Path C). When
    // --defence=promptarmor-obs, every captured tool output is
    // screened against the deployed /screen endpoint, but the
    // agent has already seen the original content — so we record
    // detection rate, not enforcement.
    "promptarmor-url": { type: "string", default: "" },
    "promptarmor-backend": { type: "string", default: "bedrock" },
    "promptarmor-model": { type: "string", default: "eu.anthropic.claude-sonnet-4-6" },
    "promptarmor-run-id": { type: "string", default: "" },
    "promptarmor-api-key": { type: "string", default: "" },
    "promptarmor-insecure": { type: "boolean", default: false },
  },
});

const scenarioFilter = values.scenario as
  | "naive"
  | "intermediate"
  | "sophisticated"
  | "all";
const model = values.model!;
const repetitions = parseInt(values.repetitions!, 10);
const defence = values.defence!;
const backend = (values.backend === "bedrock" ? "bedrock" : "ollama") as
  | "ollama"
  | "bedrock";
// Per-backend defaults — empty string from CLI means "use the
// IntentTracker's default for the chosen backend".
const embeddingModel =
  values["embedding-model"] ||
  (backend === "bedrock" ? "eu.cohere.embed-v4:0" : "nomic-embed-text");
const judgeModel =
  values["judge-model"] ||
  (backend === "bedrock" ? "eu.anthropic.claude-sonnet-4-6" : "llama3.2");
const thetaWarn = parseFloat(values["theta-warn"]!);
const thetaBlock = parseFloat(values["theta-block"]!);
const deltaWarn = parseFloat(values["delta-warn"]!);

const outputPath =
